var tape=require("tape"),protobuf=require("..");tape.test("reflected enums",function(e){var o=new protobuf.Enum("Test",{a:1,b:2}),a=new protobuf.Enum("AliasTest",{a:0},{allow_alias:!0});e.throws(function(){new protobuf.Enum("Test",!0)},TypeError,"should throw if values is specified but not an object"),e.same(o.valuesById,{1:"a",2:"b"},"should also expose their values by id"),e.throws(function(){o.add(2,2)},TypeError,"should throw if name is not a string"),e.throws(function(){o.add("c",1.5)},TypeError,"should throw if id is not an integer"),e.throws(function(){o.add("b",2)},Error,"should throw if name is a duplicate"),e.throws(function(){o.add("c",2)},Error,"should throw if id is a duplicate, without allow_alias option"),o.add("c",3),e.same(o.values,{a:1,b:2,c:3},"should allow adding new values"),e.same(o.valuesById,{1:"a",2:"b",3:"c"},"should also expose any new values by id"),e.throws(function(){o.remove(1)},TypeError,"should throw if name is not a string"),e.throws(function(){o.remove("d")},Error,"should throw if name is not present"),o.remove("b"),e.same(o.values,{a:1,c:3},"should allow removing existing values"),e.same(o.valuesById,{1:"a",3:"c"},"should no longer expose any removed values by id"),e.same(o.toJSON(),{values:{a:1,c:3}},"should export values to JSON"),a.add("b",0),e.same(a.values,{a:0,b:0}),e.end()});